sys_script_include.script:
var AutoCareBackend = Class.create();
AutoCareBackend.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getInspections: function() {

        var result = [];
        var gr = new GlideRecord('x_1947064_autoca_0_inspection');

        gr.query();

        while (gr.next()) {

            result.push({
                number: gr.getValue('inspection_number'),
                vehicle: gr.getDisplayValue('vehicle_ref'),
                appointment: gr.getDisplayValue('appointment_ref'),
                technician: gr.getDisplayValue('technician_ref'),
                date: gr.getValue('inspection_date'),
                finding: gr.getValue('finding'),
                severity: gr.getValue('severity'),
                recommendation: gr.getValue('recommendation'),
                status: gr.getValue('status')
            });
        }

        return JSON.stringify(result);
    },

    type: 'AutoCareBackend'
});
